import { Component, Input, Output, EventEmitter, forwardRef, ViewEncapsulation, input } from '@angular/core';
import { ControlValueAccessor, NG_VALUE_ACCESSOR } from '@angular/forms';
import { QaMenuComponent } from "../menu/qa-menu/qa-menu.component";
import { Question } from '../../models/ui/question.model';
import { CopyPasteDirective } from '../../directives/copy-paste.directive';
import { CommonModule } from '@angular/common';

@Component({
  selector: 'app-form-input',
  standalone: true,
  templateUrl: './form-input.component.html',
  styleUrls: ['./form-input.component.css'],
  encapsulation: ViewEncapsulation.None,
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => FormInputComponent),
      multi: true
    }
  ],
  imports: [QaMenuComponent, CopyPasteDirective,CommonModule]
})
export class FormInputComponent implements ControlValueAccessor {
  @Input() label: string = '';
  @Input() type: string = 'text';
  @Input() value: any = '';
  @Input() customStyle: { [key: string]: any } = {};
  @Output() valueChange = new EventEmitter<any>();
  question = input<Question | null>(null)
  showPopup = false;

  onChange: any = () => {};
  onTouched: any = () => {};

  writeValue(value: any): void {
    if (value !== undefined) {
      this.value = value;
    }
  }

  registerOnChange(fn: any): void {
    this.onChange = fn;
  }

  registerOnTouched(fn: any): void {
    this.onTouched = fn;
  }

  onInputChange(event: any) {
    const target = event.target;
    let value: any;

    switch (this.type) {
      case 'checkbox':
        value = target.checked;
        break;
      case 'number':
        // Use valueAsNumber for a direct numeric value, or null if empty/invalid.
        value = target.value === '' ? null : target.valueAsNumber;
        break;
      default: // 'text', 'date', 'time', 'radio', etc.
        value = target.value;
        break;
    }

    this.value = value;
    this.onChange(this.value);
    this.onTouched();
    this.valueChange.emit(this.value);
  }

  openPopup() {
    this.showPopup = true;
  }

  closePopup() {
    this.showPopup = false;
  }
}
